/**
 *
 * SelectIndicator is the dropdown indicator element for the Select component.
 *
 * [Live Demo](https://www.primereact.org/select/)
 *
 * @module SelectIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { SelectRootInstance } from './SelectRoot.types';
/**
 * Defines passthrough(pt) options type in SelectIndicator component.
 */
export type SelectIndicatorPassThroughType<E> = PassThroughType<SelectIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of SelectIndicator component.
 */
export interface SelectIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SelectIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in SelectIndicator component.
 */
export interface SelectIndicatorProps extends BaseComponentProps<SelectIndicatorInstance, unknown, SelectIndicatorPassThrough> {
    /**
     * Determines the visibility of the indicator based on the state of the select.
     * - "open": Indicator is visible when the dropdown is open.
     * - "closed": Indicator is visible when the dropdown is closed.
     * - "always": Indicator is always visible.
     * @defaultValue 'always'
     */
    match?: 'open' | 'closed' | 'always' | undefined;
}
/**
 * Defines valid state in SelectIndicator component.
 */
export interface SelectIndicatorState {
}
/**
 * Defines the methods and properties exposed by SelectIndicator component.
 */
export interface SelectIndicatorExposes {
    /**
     * The Select component instance.
     */
    select: SelectRootInstance | undefined | null;
}
/**
 * Instance of SelectIndicator component.
 */
export type SelectIndicatorInstance = ComponentInstance<SelectIndicatorProps, SelectIndicatorState, SelectIndicatorExposes>;
